assert len(emits)==len(set(emits)), [x for x,c in collections.Counter(emits).items() if c>1]
objects={k for c,k in emits if c=='objects'}
seeds={e['value']['object_key'] for item in items for e in item.get('payload',{}).get('emits',[]) if e['collection']=='seed_records'}
assert objects <= seeds, sorted(objects-seeds)
assert os.path.isfile('backend/reports/work_order_detail_export.sql')
handlers={k for c,k in emits if c=='actions' and any(e['collection']=='actions' and e['key']==k and 'handler' in e['value'] for item in items for e in item.get('payload',{}).get('emits',[]))}
scenarios=[e['value'] for item in items for e in item.get('payload',{}).get('emits',[]) if e['collection']=='acceptance_scenarios']
pos={a for s in scenarios for a in s.get('actions',[])}
neg={a for s in scenarios for a in s.get('attempted_actions',[])}
assert handlers <= pos, sorted(handlers-pos)
assert handlers <= neg, sorted(handlers-neg)
print({'items':len(items),'resources':len(emits),'objects':len(objects),'handlers':len(handlers),'seeded_objects':len(seeds),'handler_positive':len(handlers & pos),'handler_denied':len(handlers & neg)})
